def family_init(ctx):
    import math
    bars = ctx.bars
    N = len(bars)
    c = [float(b["c"]) for b in bars]
    v = [float(b.get("v") or 0.0) for b in bars]
    ts = [str(b["t"]) for b in bars]
    day = [x[:10] for x in ts]
    mod = [int(x[11:13]) * 60 + int(x[14:16]) for x in ts]

    # --- locate the session's closing bar. The closing auction makes it the
    #     largest-volume minute-of-day bucket by a wide margin; the candidate
    #     window covers 16:00 ET under either DST rule. No price is used. ---
    cm = int(ctx.p.close_min)
    if cm < 0:
        buck = {}
        for j in range(N):
            buck.setdefault(mod[j], []).append(v[j])
        best_m = None
        best_v = -1.0
        for lo, hi in ((18 * 60, 22 * 60), (0, 24 * 60)):
            for m, xs in buck.items():
                if len(xs) < 3 or m < lo or m > hi:
                    continue
                s = sorted(xs)
                md = s[len(s) // 2]
                if md > best_v:
                    best_v = md
                    best_m = m
            if best_m is not None:
                break
        cm = best_m if best_m is not None else max(mod)

    off = max(1, int(ctx.p.offset_min))
    is_close = [0] * N
    prev_close = [None] * N
    dec = [0] * N
    rrod = [None] * N

    last_close_val = None
    seen_day = None
    decided = False
    log = math.log
    for j in range(N):
        if day[j] != seen_day:
            seen_day = day[j]
            decided = False
        if not decided and (cm - off) <= mod[j] <= cm:
            dec[j] = 1
            decided = True
            p = last_close_val
            if p is not None and p > 0.0 and c[j] > 0.0:
                rrod[j] = log(c[j] / p)
        if mod[j] == cm:
            is_close[j] = 1
            last_close_val = c[j]
    ctx.dec = ctx.series(dec, "decision_bar")
    ctx.rrod = ctx.series(rrod, "rest_of_day")
    ctx.isc = ctx.series(is_close, "closing_bar")


def signal(ctx, i):
    if not ctx.dec[i]:
        return 0
    r = ctx.rrod[i]
    if r is None:
        return 0
    thr = float(ctx.p.thr)
    if r > thr:
        return 1
    if r < -thr:
        return -1
    return 0


def exit_signal(ctx, i):
    if not ctx.positions:
        return False
    return bool(ctx.isc[i])
